-- psql -v retention_at='2026-10-21T00:00:00Z' -f retention/proof-secret-preview.sql
-- Aggregate only. Work deferral takes precedence over source deferral.
BEGIN READ ONLY;
SET LOCAL statement_timeout='10s';
WITH cutoff AS(SELECT :'retention_at'::timestamptz-interval '720 hours' AS at)
SELECT 'reset' AS family,count(*) FILTER(WHERE NOT(EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AND NOT(EXISTS(SELECT 1 FROM password_reset_delivery d WHERE d.proof_id=p.id AND d.encrypted_token IS NOT NULL) OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RESET' AND b.source_id=p.id))) AS eligible_secrets,count(*) FILTER(WHERE EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AS deferred_work,count(*) FILTER(WHERE NOT(EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=p.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AND (EXISTS(SELECT 1 FROM password_reset_delivery d WHERE d.proof_id=p.id AND d.encrypted_token IS NOT NULL) OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='RESET' AND b.source_id=p.id))) AS deferred_sources FROM password_reset_proof p  CROSS JOIN cutoff c WHERE p.token_hash IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at
UNION ALL
SELECT 'email' AS family,count(*) FILTER(WHERE NOT(e.state='RECONCILING' OR e.updated_at>c.at OR(p.verified_at IS NOT NULL AND p.verified_at>c.at) OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AND NOT(EXISTS(SELECT 1 FROM email_change_delivery d WHERE d.proof_id=p.id AND d.encrypted_token IS NOT NULL) OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='EMAIL_PROOF' AND b.source_id=p.id))) AS eligible_secrets,count(*) FILTER(WHERE e.state='RECONCILING' OR e.updated_at>c.at OR(p.verified_at IS NOT NULL AND p.verified_at>c.at) OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AS deferred_work,count(*) FILTER(WHERE NOT(e.state='RECONCILING' OR e.updated_at>c.at OR(p.verified_at IS NOT NULL AND p.verified_at>c.at) OR EXISTS(SELECT 1 FROM credential_operation o WHERE o.id=e.operation_id AND(o.state NOT IN('COMPLETED','REJECTED') OR o.updated_at>c.at))) AND (EXISTS(SELECT 1 FROM email_change_delivery d WHERE d.proof_id=p.id AND d.encrypted_token IS NOT NULL) OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='EMAIL_PROOF' AND b.source_id=p.id))) AS deferred_sources FROM email_change_proof p JOIN email_change e ON e.id=p.change_id CROSS JOIN cutoff c WHERE p.token_hash IS NOT NULL AND e.expires_at<=c.at AND e.created_at<=c.at
UNION ALL
SELECT 'setup' AS family,count(*) FILTER(WHERE NOT(p.generation>i.generation OR(p.generation=i.generation AND i.expires_at>c.at) OR EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=p.invitation_id AND(t.state NOT IN('COMPLETED','REJECTED') OR t.updated_at>c.at))) AND NOT(EXISTS(SELECT 1 FROM setup_delivery d WHERE d.proof_id=p.id AND(d.encrypted_token IS NOT NULL OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='SETUP' AND b.source_id=d.id))))) AS eligible_secrets,count(*) FILTER(WHERE p.generation>i.generation OR(p.generation=i.generation AND i.expires_at>c.at) OR EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=p.invitation_id AND(t.state NOT IN('COMPLETED','REJECTED') OR t.updated_at>c.at))) AS deferred_work,count(*) FILTER(WHERE NOT(p.generation>i.generation OR(p.generation=i.generation AND i.expires_at>c.at) OR EXISTS(SELECT 1 FROM setup_intent t WHERE t.invitation_id=p.invitation_id AND(t.state NOT IN('COMPLETED','REJECTED') OR t.updated_at>c.at))) AND (EXISTS(SELECT 1 FROM setup_delivery d WHERE d.proof_id=p.id AND(d.encrypted_token IS NOT NULL OR EXISTS(SELECT 1 FROM external_delivery_retention_blocker b WHERE b.source_kind='SETUP' AND b.source_id=d.id))))) AS deferred_sources FROM setup_email_proof p JOIN setup_invitation i ON i.id=p.invitation_id CROSS JOIN cutoff c WHERE p.token_hash IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at
UNION ALL
SELECT 'device' AS family,count(*) FILTER(WHERE NOT(p.state IN('SENDING','UNKNOWN')) AND NOT(FALSE)) AS eligible_secrets,count(*) FILTER(WHERE p.state IN('SENDING','UNKNOWN')) AS deferred_work,count(*) FILTER(WHERE NOT(p.state IN('SENDING','UNKNOWN')) AND (FALSE)) AS deferred_sources FROM device_verification p  CROSS JOIN cutoff c WHERE p.code_hash IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at
UNION ALL
SELECT 'oauth' AS family,count(*) FILTER(WHERE NOT(p.state='CLAIMED') AND NOT(FALSE)) AS eligible_secrets,count(*) FILTER(WHERE p.state='CLAIMED') AS deferred_work,count(*) FILTER(WHERE NOT(p.state='CLAIMED') AND (FALSE)) AS deferred_sources FROM external_challenge p  CROSS JOIN cutoff c WHERE p.encrypted_verifier IS NOT NULL AND p.expires_at<=c.at AND p.created_at<=c.at
ORDER BY family;
ROLLBACK;
